import { afterEach, describe, expect, it, jest } from '@jest/globals';

import { ApiError, apiRequest } from './client';

const realFetch = globalThis.fetch;
afterEach(() => {
  globalThis.fetch = realFetch;
});

function mockFetch(impl: () => Promise<Response>) {
  globalThis.fetch = jest.fn(impl) as unknown as typeof fetch;
}

const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
  Promise.resolve(new Response(JSON.stringify(body), { status, headers }));

async function fail(method: 'GET' | 'POST' = 'GET'): Promise<ApiError> {
  try {
    await apiRequest('/v1/x', { token: 't', method, body: method === 'POST' ? {} : undefined });
  } catch (e) {
    return e as ApiError;
  }
  throw new Error('expected failure');
}

describe('apiRequest errors', () => {
  it('maps the documented error body', async () => {
    mockFetch(() => json(400, { error: { code: 'VALIDATION', message: 'bad', field: 'amount' } }));
    const e = await fail('POST');
    expect([e.status, e.code, e.field, e.isUnknownOutcome]).toEqual([400, 'VALIDATION', 'amount', false]);
  });

  it('504 on POST is an unknown outcome, on GET it is not', async () => {
    mockFetch(() => json(504, { error: { code: 'TIMEOUT', message: 't' } }));
    expect((await fail('POST')).isUnknownOutcome).toBe(true);
    expect((await fail('GET')).isUnknownOutcome).toBe(false);
  });

  it('network failure on POST is an unknown outcome', async () => {
    mockFetch(() => Promise.reject(new TypeError('Failed to fetch')));
    const e = await fail('POST');
    expect([e.status, e.code, e.isUnknownOutcome]).toEqual([0, 'NETWORK', true]);
  });

  it('401 is unauthorized; 429 takes Retry-After header when body has none', async () => {
    mockFetch(() => json(401, { error: { code: 'UNAUTHORIZED', message: 'no' } }));
    expect((await fail()).isUnauthorized).toBe(true);
    mockFetch(() => json(429, { error: { code: 'RATE_LIMITED', message: 'slow' } }, { 'Retry-After': '2' }));
    expect((await fail()).retryAfterMs).toBe(2000);
  });

  it('non-JSON error body still maps by status', async () => {
    mockFetch(() => Promise.resolve(new Response('<html>bad gateway</html>', { status: 502 })));
    const e = await fail();
    expect([e.code, e.isTransient]).toEqual(['SERVER', true]);
  });
});
import { API_BASE_URL } from '@/config';

import type { ApiErrorBody } from './types';

/** Server codes from the docs, plus client-side ones. */
export type ApiErrorCodeOrClient =
  | ApiErrorBody['error']['code']
  | 'NETWORK' // request never got a response (offline, DNS, CORS, aborted)
  | 'BAD_RESPONSE'; // response body was not the JSON we expected

export class ApiError extends Error {
  readonly status: number; // 0 when there was no HTTP response
  readonly code: ApiErrorCodeOrClient;
  readonly field?: string;
  readonly retryAfterMs?: number;
  readonly method: string;

  constructor(opts: {
    status: number;
    code: ApiErrorCodeOrClient;
    message: string;
    method: string;
    field?: string;
    retryAfterMs?: number;
  }) {
    super(opts.message);
    this.name = 'ApiError';
    this.status = opts.status;
    this.code = opts.code;
    this.method = opts.method;
    this.field = opts.field;
    this.retryAfterMs = opts.retryAfterMs;
  }

  /** Token missing/invalid/expired: the UI should clear the token. */
  get isUnauthorized(): boolean {
    return this.status === 401 || this.code === 'UNAUTHORIZED';
  }

  /**
   * For non-GET requests: the server may or may not have applied the request
   * (504 TIMEOUT, or no response at all). Retry with the SAME idempotency key
   * or poll; never treat this as "failed".
   */
  get isUnknownOutcome(): boolean {
    if (this.method === 'GET') return false;
    return this.status === 504 || this.code === 'TIMEOUT' || this.code === 'NETWORK';
  }

  /** Worth retrying automatically (for idempotent/GET requests). */
  get isTransient(): boolean {
    return (
      this.code === 'NETWORK' ||
      this.code === 'RATE_LIMITED' ||
      this.code === 'SERVER' ||
      this.code === 'TIMEOUT' ||
      this.status >= 500
    );
  }
}

export function isApiError(e: unknown): e is ApiError {
  return e instanceof ApiError;
}

export type RequestOptions = {
  token: string;
  method?: 'GET' | 'POST';
  query?: Record<string, string | number | undefined | null>;
  body?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
};

function buildUrl(path: string, query?: RequestOptions['query']): string {
  const url = new URL(path, API_BASE_URL);
  if (query) {
    for (const [k, v] of Object.entries(query)) {
      if (v !== undefined && v !== null) url.searchParams.set(k, String(v));
    }
  }
  return url.toString();
}

function parseRetryAfter(res: Response, bodyMs?: number): number | undefined {
  if (typeof bodyMs === 'number' && Number.isFinite(bodyMs)) return bodyMs;
  const header = res.headers.get('Retry-After');
  if (header == null) return undefined;
  const seconds = Number(header);
  return Number.isFinite(seconds) ? seconds * 1000 : undefined;
}

function fallbackCode(status: number): ApiErrorCodeOrClient {
  if (status === 400) return 'VALIDATION';
  if (status === 401) return 'UNAUTHORIZED';
  if (status === 404) return 'NOT_FOUND';
  if (status === 409) return 'IDEMPOTENCY_MISMATCH';
  if (status === 429) return 'RATE_LIMITED';
  if (status === 504) return 'TIMEOUT';
  if (status >= 500) return 'SERVER';
  return 'BAD_RESPONSE';
}

export async function apiRequest<T>(path: string, opts: RequestOptions): Promise<T> {
  const method = opts.method ?? 'GET';
  const headers: Record<string, string> = {
    Accept: 'application/json',
    Authorization: `Bearer ${opts.token}`,
    ...opts.headers,
  };
  if (opts.body !== undefined) headers['Content-Type'] = 'application/json';

  let res: Response;
  try {
    res = await fetch(buildUrl(path, opts.query), {
      method,
      headers,
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
      signal: opts.signal,
    });
  } catch (e) {
    // Let React Query cancellations propagate untouched.
    if (opts.signal?.aborted) throw e;
    throw new ApiError({
      status: 0,
      code: 'NETWORK',
      method,
      message: 'Could not reach the server. Check your connection.',
    });
  }

  let json: unknown = undefined;
  const text = await res.text().catch(() => '');
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = undefined;
    }
  }

  if (!res.ok) {
    const err = (json as Partial<ApiErrorBody> | undefined)?.error;
    throw new ApiError({
      status: res.status,
      code: err?.code ?? fallbackCode(res.status),
      method,
      message: err?.message ?? `Request failed (${res.status})`,
      field: err?.field,
      retryAfterMs: res.status === 429 ? parseRetryAfter(res, err?.retryAfterMs) : err?.retryAfterMs,
    });
  }

  if (json === undefined) {
    throw new ApiError({
      status: res.status,
      code: 'BAD_RESPONSE',
      method,
      message: 'Unexpected response from the server.',
    });
  }
  return json as T;
}
import { useQuery } from '@tanstack/react-query';
import { useAtomValue } from 'jotai';

import { tokenAtom } from '@/state/token';

import { getBalances } from './services';

export const queryKeys = {
  balances: ['balances'] as const,
  activity: ['activity'] as const,
  claimOptions: (asset: string) => ['claim-options', asset] as const,
  claim: (id: string) => ['claim', id] as const,
};

/** Token for API calls; screens behind TokenGate always have one. */
export function useToken(): string {
  const token = useAtomValue(tokenAtom);
  if (!token) throw new Error('useToken used outside TokenGate');
  return token;
}

// Server recomputes balances every 15s, so polling faster is pointless.
export const BALANCES_REFETCH_MS = 15_000;

export function useBalances() {
  const token = useToken();
  return useQuery({
    queryKey: queryKeys.balances,
    queryFn: ({ signal }) => getBalances(token, signal),
    refetchInterval: BALANCES_REFETCH_MS,
  });
}
import { MutationCache, QueryCache, QueryClient } from '@tanstack/react-query';

import { saveSubmission } from '@/lib/claim-submit';
import { appStore } from '@/state/store';
import { signOutReasonAtom, tokenAtom } from '@/state/token';

import { isApiError } from './client';

const MAX_QUERY_RETRIES = 3;

/** Clears the token and all cached data of the previous token. `reason` is shown on the token screen. */
export function signOut(reason: string | null = null) {
  appStore.set(signOutReasonAtom, reason);
  appStore.set(tokenAtom, null);
  queryClient.clear();
  // An unresolved claim belongs to this token; resuming it under another token would claim on that account.
  saveSubmission(null);
}

function onApiError(error: unknown) {
  // Token missing/invalid/expired anywhere -> back to the token screen.
  if (isApiError(error) && error.isUnauthorized) {
    signOut('Your token was rejected or has expired. Enter a valid token.');
  }
}

export const queryClient: QueryClient = new QueryClient({
  queryCache: new QueryCache({ onError: onApiError }),
  mutationCache: new MutationCache({ onError: onApiError }),
  defaultOptions: {
    queries: {
      // GETs are safe to retry, but only for transient failures.
      retry: (failureCount, error) =>
        failureCount < MAX_QUERY_RETRIES && isApiError(error) && error.isTransient,
      // Honour 429 retryAfterMs; otherwise exponential backoff capped at 8s.
      retryDelay: (attempt, error) =>
        (isApiError(error) && error.retryAfterMs) || Math.min(1000 * 2 ** attempt, 8000),
      refetchOnWindowFocus: true,
    },
    mutations: {
      // Never auto-retry writes; the claim flow retries explicitly with the same idempotency key.
      retry: false,
    },
  },
});
import { apiRequest } from './client';
import type {
  ActivityResponse,
  BalancesResponse,
  Claim,
  ClaimOptions,
  CreateClaimBody,
} from './types';

// Thin typed wrappers over the documented endpoints. Each takes the token
// explicitly so callers (React Query hooks) control where it comes from.

export function getBalances(token: string, signal?: AbortSignal) {
  return apiRequest<BalancesResponse>('/v1/balances', { token, signal });
}

export const ACTIVITY_PAGE_SIZE = 20;

export function getActivity(token: string, cursor?: string | null, signal?: AbortSignal) {
  return apiRequest<ActivityResponse>('/v1/activity', {
    token,
    signal,
    query: { limit: ACTIVITY_PAGE_SIZE, cursor },
  });
}

export function getClaimOptions(token: string, asset: string, signal?: AbortSignal) {
  return apiRequest<ClaimOptions>('/v1/claim-options', { token, signal, query: { asset } });
}

/**
 * Creates a claim. Reuse the same idempotencyKey when retrying after an
 * unknown outcome (504 / network error): the server returns the original
 * claim instead of creating a second one. A new attempt needs a new key.
 */
export function createClaim(token: string, body: CreateClaimBody, idempotencyKey: string) {
  return apiRequest<Claim>('/v1/claims', {
    token,
    method: 'POST',
    body,
    headers: { 'Idempotency-Key': idempotencyKey },
  });
}

export function getClaim(token: string, id: string, signal?: AbortSignal) {
  return apiRequest<Claim>(`/v1/claims/${encodeURIComponent(id)}`, { token, signal });
}
// Wire types, matching https://task-api.cashmine.io/docs exactly.
// Amounts are decimal strings in the asset's unit and are never converted to JS numbers.

export type DecimalString = string;
export type IsoDateString = string;

export type Balance = {
  asset: string;
  decimals: number;
  available: DecimalString;
  pending: DecimalString;
  claiming: DecimalString;
  usdPrice: DecimalString;
};

export type BalancesResponse = {
  asOf: IsoDateString;
  items: Balance[];
};

export type ActivityType = 'accrual' | 'reversal' | 'claim';
// accrual: pending | confirmed; reversal: confirmed; claim: pending | completed | failed
export type ActivityStatus = 'pending' | 'confirmed' | 'completed' | 'failed';

export type ActivityItem = {
  id: string;
  type: ActivityType;
  asset: string;
  /** Signed: negative for reversals and claims. */
  amount: DecimalString;
  status: ActivityStatus;
  /** null for claims */
  exchange: string | null;
  createdAt: IsoDateString;
  /** reversal: the accrual id; claim: the claim id (null for older claims) */
  relatedId: string | null;
};

export type ActivityResponse = {
  items: ActivityItem[];
  nextCursor: string | null;
};

export type ClaimDestination = {
  id: string;
  label: string;
};

export type ClaimOptions = {
  asset: string;
  minAmount: DecimalString;
  /** Taken from the claimed amount: receive = amount - fee. */
  fee: DecimalString;
  destinations: ClaimDestination[];
};

export type CreateClaimBody = {
  asset: string;
  amount: DecimalString;
  destinationId: string;
};

export type ClaimStatus = 'pending' | 'completed' | 'failed';

export type Claim = {
  id: string;
  asset: string;
  amount: DecimalString;
  fee: DecimalString;
  receiveAmount: DecimalString;
  destinationId: string;
  status: ClaimStatus;
  failureReason: string | null;
  createdAt: IsoDateString;
  updatedAt: IsoDateString;
};

export type ApiErrorCode =
  | 'VALIDATION'
  | 'UNAUTHORIZED'
  | 'NOT_FOUND'
  | 'IDEMPOTENCY_MISMATCH'
  | 'RATE_LIMITED'
  | 'SERVER'
  | 'TIMEOUT';

export type ApiErrorBody = {
  error: {
    code: ApiErrorCode | string;
    message: string;
    field?: string;
    retryAfterMs?: number;
  };
};
